/**
 * The following functionality is available:

- Initiate the phone number change process for signed in users.
- Change to a new phone number during the phone number verification
  process at signup for unauthenticated users. Note that this requires:
  `ACCOUNT_PHONE_VERIFICATION_SUPPORTS_CHANGE = True`.

In both cases, after posting a new phone number, proceed with the phone
verification endpoint to confirm the change of the phone number by
posting the verification code.

 * @summary Change the phone number

 */
export type phoneChangeResponse202 = {
  data: PhoneNumberChangeResponse
  status: 202
}

export type phoneChangeResponse400 = {
  data: ErrorResponse
  status: 400
}

export type phoneChangeResponse401 = {
  data: AuthenticationOrReauthenticationResponse
  status: 401
}

export type phoneChangeResponse409 = {
  data: ConflictResponse
  status: 409
}
    
export type phoneChangeResponseSuccess = (phoneChangeResponse202) & {
  headers: Headers;
};
export type phoneChangeResponseError = (phoneChangeResponse400 | phoneChangeResponse401 | phoneChangeResponse409) & {
  headers: Headers;
};

export type phoneChangeResponse = (phoneChangeResponseSuccess | phoneChangeResponseError)

export const getPhoneChangeUrl = () => {


  

  return `/_allauth/browser/v1/account/phone`
}

export const phoneChange = async (phoneBody: PhoneBody, options?: RequestInit): Promise<phoneChangeResponse> => {
  
  return identityFetch<phoneChangeResponse>(getPhoneChangeUrl(),
  {      
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...options?.headers },
    body: JSON.stringify(
      phoneBody,)
  }
);}




